import React, { useCallback, useEffect, useRef, useState } from 'react';
import { Box, Button, Paper, Typography } from '@mui/material';
import { DEMO_VENUES } from '../data/venues';
import {
  addPin,
  battleTarget,
  bearingDeg,
  clearCompassTarget,
  deletePin,
  distanceMeters,
  formatDistance,
  loadChosenVenueId,
  loadCompassTarget,
  loadPins,
  nearestBattleVenue,
  pinTarget,
  setCompassTarget,
  stationTarget,
  subscribeCompassChanges,
  venueTarget,
  wildTarget,
  wrapDeg,
  type CompassTarget,
  type GeoFix,
  type PersonalPin,
} from '../utils/compass';
import { useOwnerMode } from '../utils/ownerMode';
import {
  HOME_STATION_EVENT,
  HOME_STATION_ID,
  homeStationRefill,
  loadHomeStation,
  type HomeStationAnchor,
} from '../utils/homeStation';

// STROLL COMPASS (Round 33.5, Eddie 2026-11-18 ~15:30 PT).
//
// A small glass compass riding the bottom-right of the Stroll
// scene (Round 23 law: the scene stays clean — it is compact,
// and it can be hidden down to a dot). It guides the player to
// ONE chosen target with a direction arrow + live distance:
//   🏟 a venue the player chose ("🧭 Guide me there" on the
//      venue's World Map panel writes the same target record),
//   ⚔️ the nearest Battle Night battle spot (demo venue data),
//   🌿 the live Round 13 wild spawn, while one stands in the
//      scene — walking to it meets the EXISTING encounter card,
//      which stays the one and only battle approval,
//   📌 the player's own personal pin ("remember where I parked
//      my car") — pins live only in this phone's localStorage,
//      are never on the shared map/heat, never sent anywhere,
//      and are visible to nobody else. The pins UI says so.
//
// THE COMPASS NEVER POINTS TO PEOPLE. There is no person
// target kind — targets are places, spawns and your own pins.
//
// POSITION: everything is computed on-device. Geo targets use
// the latest geolocation fix (held in the page's ref — never
// stored, never sent; this component runs its own watch while
// a geo target is active or the picker is open, and the Stroll
// page's "📍 Walk with me" watch feeds the same ref). The wild
// target uses scene units (the scene's own frame: 3 units = 1 m,
// the same scale GPS mode walks at).
//
// HEADING (stated plainly, per the round brief): for geo targets
// the arrow is relative to the device's course over ground while
// the player is actually moving (a fix carrying heading+speed);
// otherwise it falls back to NORTH-UP — the arrow shows the
// absolute bearing and the dial marks N. For the wild target the
// arrow is relative to the walker's facing in the scene.

const SCENE_UNITS_PER_METRE = 3; // Stroll's GPS scale (1 m = 3 units)
const GEO_ARRIVE_M = 25;
const WILD_ARRIVE_UNITS = 3;

const GLASS_SX = {
  color: '#eaf6fa',
  backgroundColor: 'rgba(13, 47, 63, 0.55)',
  backdropFilter: 'blur(10px)',
  WebkitBackdropFilter: 'blur(10px)',
  border: '1px solid rgba(120, 200, 225, 0.34)',
  boxShadow: '0 6px 18px rgba(0, 0, 0, 0.55)',
};

const TARGET_EMOJI: Record<CompassTarget['kind'], string> = {
  venue: '🏟',
  battle: '⚔️',
  wild: '🌿',
  pin: '📌',
  station: '🧪',
};

interface Guidance {
  distanceM: number | null;
  arrowDeg: number | null;
  bearing: number | null;
  headingSource: 'course' | 'walker' | 'north' | null;
  arrived: boolean;
  note: string | null;
}

const NO_GUIDANCE: Guidance = {
  distanceM: null,
  arrowDeg: null,
  bearing: null,
  headingSource: null,
  arrived: false,
  note: null,
};

interface StrollCompassProps {
  walkerRef: React.MutableRefObject<{ x: number; z: number; heading: number } | null>;
  encounterPosRef: React.MutableRefObject<{ x: number; z: number } | null>;
  playerGeoRef: React.MutableRefObject<GeoFix | null>;
  // The live Round 13 encounter (page state), or null.
  wildActive: { name: string } | null;
}

const StrollCompass: React.FC<StrollCompassProps> = ({
  walkerRef,
  encounterPosRef,
  playerGeoRef,
  wildActive,
}) => {
  const [target, setTarget] = useState<CompassTarget | null>(() => loadCompassTarget());
  const [pins, setPins] = useState<PersonalPin[]>(() => loadPins());
  // The owner's Home Station (Round 36.9 Part 9) as a guide
  // target — owner-only, read from the on-device store, kept in
  // step through its change event like the pins above.
  const ownerMode = useOwnerMode();
  const [homeAnchor, setHomeAnchor] = useState<HomeStationAnchor | null>(() => loadHomeStation());
  useEffect(() => {
    const sync = () => setHomeAnchor(loadHomeStation());
    window.addEventListener(HOME_STATION_EVENT, sync);
    window.addEventListener('storage', sync);
    return () => {
      window.removeEventListener(HOME_STATION_EVENT, sync);
      window.removeEventListener('storage', sync);
    };
  }, []);
  const [chosenVenueId, setChosenVenueId] = useState<string | null>(() => loadChosenVenueId());
  const [pickerOpen, setPickerOpen] = useState(false);
  const [hidden, setHidden] = useState(false);
  const [pinName, setPinName] = useState('');
  const [pinNote, setPinNote] = useState<string | null>(null);
  const [geoStatus, setGeoStatus] = useState<'ok' | 'denied' | 'unavailable' | null>(null);
  const [guidance, setGuidance] = useState<Guidance>(NO_GUIDANCE);
  const guidanceJsonRef = useRef('');
  // While the picker is open, a 1s tick keeps its per-row
  // distances (read from the geo ref at render) fresh.
  const [, setPickerTick] = useState(0);
  useEffect(() => {
    if (!pickerOpen) return;
    const id = window.setInterval(() => setPickerTick(t => t + 1), 1000);
    return () => window.clearInterval(id);
  }, [pickerOpen]);

  // Keep every compass-store reader in step (the venue panel on
  // the map writes the target; this component is a reader too).
  useEffect(
    () =>
      subscribeCompassChanges(() => {
        setTarget(loadCompassTarget());
        setPins(loadPins());
        setChosenVenueId(loadChosenVenueId());
      }),
    []
  );

  // A wild target lives only while its spawn stands: when the
  // encounter ends (fought, released, despawned, left), the
  // target clears itself — there is nothing left to guide to.
  useEffect(() => {
    if (target?.kind === 'wild' && !wildActive) clearCompassTarget();
  }, [target, wildActive]);

  const targetIsGeo = !!target && target.kind !== 'wild';

  // On-device position watch for geo guidance: runs while a geo
  // target is active or the picker is open (the picker shows pin
  // distances and drops pins). Fixes land in the page's ref only
  // — never stored, never sent. Where geolocation is missing or
  // denied the compass says so instead of pretending.
  useEffect(() => {
    if (!targetIsGeo && !pickerOpen) return;
    if (!('geolocation' in navigator) || !navigator.geolocation.watchPosition) {
      setGeoStatus('unavailable');
      return;
    }
    const watchId = navigator.geolocation.watchPosition(
      pos => {
        playerGeoRef.current = {
          lat: pos.coords.latitude,
          lng: pos.coords.longitude,
          heading: pos.coords.heading,
          speed: pos.coords.speed,
          ts: Date.now(),
        };
        setGeoStatus('ok');
      },
      () => setGeoStatus('denied'),
      { enableHighAccuracy: true, maximumAge: 1000 }
    );
    return () => navigator.geolocation.clearWatch(watchId);
  }, [targetIsGeo, pickerOpen, playerGeoRef]);

  // The guidance tick: 4×/s, recompute from the refs and publish
  // only on change (the picker reads the same refs at render).
  useEffect(() => {
    const compute = (): Guidance => {
      if (!target) return NO_GUIDANCE;
      if (target.kind === 'wild') {
        const walker = walkerRef.current;
        const pos = encounterPosRef.current;
        if (!wildActive || !walker || !pos) {
          return { ...NO_GUIDANCE, note: 'The wild navitar is gone.' };
        }
        const dx = pos.x - walker.x;
        const dz = pos.z - walker.z;
        const distUnits = Math.hypot(dx, dz);
        // Scene frame is map-aligned (GPS mode: +x = east,
        // −z = north), so bearings read like the real compass.
        const bearing = (Math.atan2(dx, -dz) * 180) / Math.PI;
        const headingBearing =
          (Math.atan2(Math.sin(walker.heading), -Math.cos(walker.heading)) * 180) / Math.PI;
        return {
          distanceM: distUnits / SCENE_UNITS_PER_METRE,
          arrowDeg: wrapDeg(bearing - headingBearing),
          bearing: (bearing + 360) % 360,
          headingSource: 'walker',
          arrived: distUnits <= WILD_ARRIVE_UNITS,
          note: null,
        };
      }
      const fix = playerGeoRef.current;
      if (!fix) {
        return {
          ...NO_GUIDANCE,
          note:
            geoStatus === 'denied' || geoStatus === 'unavailable'
              ? 'Location is off — the compass needs it to guide you. Nothing is stored or sent.'
              : 'Finding you… your position stays on this phone.',
        };
      }
      const distanceM = distanceMeters(fix, target);
      const bearing = bearingDeg(fix, target);
      const moving = fix.heading !== null && (fix.speed ?? 0) >= 0.5;
      return {
        distanceM,
        arrowDeg: moving ? wrapDeg(bearing - (fix.heading ?? 0)) : bearing,
        bearing,
        headingSource: moving ? 'course' : 'north',
        arrived: distanceM < GEO_ARRIVE_M,
        note: null,
      };
    };
    const id = window.setInterval(() => {
      const g = compute();
      const json = JSON.stringify(g);
      if (json !== guidanceJsonRef.current) {
        guidanceJsonRef.current = json;
        setGuidance(g);
      }
    }, 250);
    return () => window.clearInterval(id);
  }, [target, wildActive, geoStatus, walkerRef, encounterPosRef, playerGeoRef]);

  const pickTarget = useCallback((t: CompassTarget) => {
    setCompassTarget(t);
    setPinNote(null);
  }, []);

  const dropPin = useCallback(() => {
    const name = pinName.trim() || 'My spot';
    const useFix = (fix: GeoFix) => {
      const pin = addPin(name, fix.lat, fix.lng);
      setCompassTarget(pinTarget(pin));
      setPinName('');
      setPinNote(`📌 “${pin.name}” saved on this phone — the compass is guiding you to it.`);
    };
    const fresh =
      playerGeoRef.current && Date.now() - playerGeoRef.current.ts < 30000
        ? playerGeoRef.current
        : null;
    if (fresh) {
      useFix(fresh);
      return;
    }
    if (!('geolocation' in navigator) || !navigator.geolocation.getCurrentPosition) {
      setPinNote('This device has no location — a pin needs your real spot. Nothing was saved.');
      return;
    }
    navigator.geolocation.getCurrentPosition(
      pos => {
        const fix: GeoFix = {
          lat: pos.coords.latitude,
          lng: pos.coords.longitude,
          heading: pos.coords.heading,
          speed: pos.coords.speed,
          ts: Date.now(),
        };
        playerGeoRef.current = fix;
        useFix(fix);
      },
      () => setPinNote('Location is off — a pin needs your real spot. Nothing was saved.'),
      { enableHighAccuracy: true, timeout: 10000 }
    );
  }, [pinName, playerGeoRef]);

  const removePin = useCallback((id: string) => {
    deletePin(id);
    setPinNote(null);
  }, []);

  const chosenVenue = chosenVenueId
    ? (DEMO_VENUES.find(v => v.id === chosenVenueId) ?? null)
    : null;
  const fixNow = playerGeoRef.current;
  const battleVenue = nearestBattleVenue(fixNow);
  const isCurrent = (kind: CompassTarget['kind'], id?: string) =>
    !!target &&
    target.kind === kind &&
    (id === undefined || (target.kind !== 'wild' && target.id === id));

  if (hidden) {
    return (
      <Button
        data-testid="stroll-compass-dot"
        aria-label="Show the compass"
        onClick={() => setHidden(false)}
        sx={{
          position: 'absolute',
          right: 16,
          bottom: 16,
          zIndex: 3,
          minWidth: 0,
          width: 38,
          height: 38,
          borderRadius: '50%',
          ...GLASS_SX,
        }}
      >
        🧭
      </Button>
    );
  }

  const statusLine = !target
    ? 'Guide me'
    : guidance.arrived
      ? 'You’re here 📍'
      : guidance.distanceM !== null
        ? formatDistance(guidance.distanceM)
        : guidance.note
          ? guidance.note.split(' — ')[0]
          : '…';

  return (
    <Box
      sx={{
        position: 'absolute',
        right: 16,
        bottom: 16,
        zIndex: 3,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'flex-end',
        gap: 1,
        maxWidth: 'calc(100% - 32px)',
      }}
    >
      {pickerOpen && (
        <Paper
          data-testid="stroll-compass-picker"
          elevation={6}
          sx={{
            p: 1.5,
            borderRadius: 3,
            width: 'min(320px, calc(100vw - 64px))',
            maxHeight: '52vh',
            overflowY: 'auto',
            bgcolor: 'rgba(10, 26, 34, 0.94)',
            backdropFilter: 'blur(10px)',
            color: '#e8f6fb',
            border: '1px solid rgba(120, 200, 225, 0.25)',
          }}
        >
          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
              🧭 Compass
            </Typography>
            <Button
              size="small"
              aria-label="Close compass picker"
              onClick={() => setPickerOpen(false)}
              sx={{ color: 'inherit', minWidth: 0, px: 1 }}
            >
              ✕
            </Button>
          </Box>
          <Typography variant="caption" sx={{ opacity: 0.85, display: 'block', mb: 1 }}>
            Guides to places and spawns — never to people.
          </Typography>

          {target && (
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
              <Typography variant="body2" sx={{ flex: 1, minWidth: 0 }}>
                {TARGET_EMOJI[target.kind]} Guiding to <strong>{target.label}</strong>
                {guidance.distanceM !== null ? ` · ${formatDistance(guidance.distanceM)}` : ''}
              </Typography>
              <Button
                size="small"
                variant="outlined"
                data-testid="compass-clear-target"
                onClick={() => clearCompassTarget()}
                sx={{ color: '#e8f6fb', borderColor: 'rgba(232,246,251,0.5)', flexShrink: 0 }}
              >
                ✕ Clear
              </Button>
            </Box>
          )}

          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.75 }}>
            {chosenVenue && (
              <Button
                variant={isCurrent('venue', chosenVenue.id) ? 'contained' : 'outlined'}
                data-testid="compass-target-venue"
                onClick={() => pickTarget(venueTarget(chosenVenue))}
                sx={{
                  justifyContent: 'flex-start',
                  color: '#e8f6fb',
                  borderColor: 'rgba(232,246,251,0.4)',
                  textTransform: 'none',
                }}
              >
                🏟 {chosenVenue.name}
                <Typography component="span" variant="caption" sx={{ ml: 1, opacity: 0.8 }}>
                  your chosen venue · demo
                </Typography>
              </Button>
            )}
            {battleVenue && (
              <Button
                variant={isCurrent('battle', battleVenue.id) ? 'contained' : 'outlined'}
                data-testid="compass-target-battle"
                onClick={() => pickTarget(battleTarget(battleVenue))}
                sx={{
                  justifyContent: 'flex-start',
                  color: '#e8f6fb',
                  borderColor: 'rgba(232,246,251,0.4)',
                  textTransform: 'none',
                }}
              >
                ⚔️ Battle Night — {battleVenue.name}
                <Typography component="span" variant="caption" sx={{ ml: 1, opacity: 0.8 }}>
                  nearest battle spot · demo
                  {fixNow ? ` · ${formatDistance(distanceMeters(fixNow, battleVenue))}` : ''}
                </Typography>
              </Button>
            )}
            {wildActive && (
              <Button
                variant={isCurrent('wild') ? 'contained' : 'outlined'}
                data-testid="compass-target-wild"
                onClick={() => pickTarget(wildTarget(wildActive.name))}
                sx={{
                  justifyContent: 'flex-start',
                  color: '#e8f6fb',
                  borderColor: 'rgba(232,246,251,0.4)',
                  textTransform: 'none',
                }}
              >
                🌿 Wild {wildActive.name}
                <Typography component="span" variant="caption" sx={{ ml: 1, opacity: 0.8 }}>
                  standing in this stroll — walk to it
                </Typography>
              </Button>
            )}
            {ownerMode && homeAnchor && (
              <Button
                variant={isCurrent('station', HOME_STATION_ID) ? 'contained' : 'outlined'}
                data-testid="compass-target-station"
                onClick={() => pickTarget(stationTarget(homeStationRefill(homeAnchor)))}
                sx={{
                  justifyContent: 'flex-start',
                  color: '#e8f6fb',
                  borderColor: 'rgba(232,246,251,0.4)',
                  textTransform: 'none',
                }}
              >
                🧪 Home Station
                <Typography component="span" variant="caption" sx={{ ml: 1, opacity: 0.8 }}>
                  your refill station · only on this phone
                  {fixNow ? ` · ${formatDistance(distanceMeters(fixNow, homeAnchor))}` : ''}
                </Typography>
              </Button>
            )}
          </Box>

          <Typography variant="subtitle2" sx={{ mt: 2, fontWeight: 700 }}>
            📌 Your pins
          </Typography>
          <Typography variant="caption" sx={{ opacity: 0.85, display: 'block' }}>
            Only you can see your pins.
          </Typography>
          <Typography variant="caption" sx={{ opacity: 0.7, display: 'block', mb: 1 }}>
            Pins live only on this phone — never on the shared map, never shared, never sent
            anywhere.
          </Typography>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.75 }}>
            {pins.map(pin => (
              <Box key={pin.id} sx={{ display: 'flex', alignItems: 'center', gap: 0.75 }}>
                <Button
                  variant={isCurrent('pin', pin.id) ? 'contained' : 'outlined'}
                  data-testid={`compass-pin-${pin.id}`}
                  onClick={() => pickTarget(pinTarget(pin))}
                  sx={{
                    flex: 1,
                    justifyContent: 'flex-start',
                    color: '#e8f6fb',
                    borderColor: 'rgba(232,246,251,0.4)',
                    textTransform: 'none',
                    minWidth: 0,
                  }}
                >
                  📌 {pin.name}
                  {fixNow && (
                    <Typography component="span" variant="caption" sx={{ ml: 1, opacity: 0.8 }}>
                      {formatDistance(distanceMeters(fixNow, pin))}
                    </Typography>
                  )}
                </Button>
                <Button
                  size="small"
                  aria-label={`Delete pin ${pin.name}`}
                  data-testid={`compass-pin-delete-${pin.id}`}
                  onClick={() => removePin(pin.id)}
                  sx={{ color: '#e8f6fb', minWidth: 0, px: 1, flexShrink: 0 }}
                >
                  🗑
                </Button>
              </Box>
            ))}
            {pins.length === 0 && (
              <Typography variant="body2" sx={{ opacity: 0.8 }}>
                No pins yet — drop one where you’re standing and the compass will guide you back.
              </Typography>
            )}
          </Box>
          <Box sx={{ display: 'flex', gap: 0.75, mt: 1 }}>
            <input
              data-testid="compass-pin-name"
              value={pinName}
              onChange={e => setPinName(e.target.value)}
              placeholder="Name it — e.g. My car"
              aria-label="Name for the new pin"
              style={{
                flex: 1,
                minWidth: 0,
                padding: '8px 10px',
                borderRadius: 8,
                border: '1px solid rgba(120, 200, 225, 0.4)',
                background: 'rgba(232, 246, 251, 0.08)',
                color: '#e8f6fb',
                fontSize: '0.85rem',
              }}
            />
            <Button
              variant="contained"
              size="small"
              data-testid="compass-pin-add"
              onClick={dropPin}
              sx={{ flexShrink: 0, textTransform: 'none' }}
            >
              📌 Remember this spot
            </Button>
          </Box>
          {pinNote && (
            <Typography variant="caption" sx={{ display: 'block', mt: 1, opacity: 0.9 }}>
              {pinNote}
            </Typography>
          )}

          <Box
            sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mt: 2 }}
          >
            <Typography variant="caption" sx={{ opacity: 0.7 }}>
              Demo places, shown honestly.
            </Typography>
            <Button
              size="small"
              data-testid="compass-hide"
              onClick={() => {
                setPickerOpen(false);
                setHidden(true);
              }}
              sx={{ color: 'inherit', textTransform: 'none' }}
            >
              Hide compass
            </Button>
          </Box>
        </Paper>
      )}

      <Button
        data-testid="stroll-compass"
        data-target-kind={target?.kind ?? ''}
        data-distance-m={guidance.distanceM !== null ? String(Math.round(guidance.distanceM)) : ''}
        data-bearing-deg={guidance.bearing !== null ? String(Math.round(guidance.bearing)) : ''}
        data-heading-source={guidance.headingSource ?? ''}
        data-arrived={guidance.arrived ? '1' : ''}
        aria-label={
          target
            ? `Compass guiding to ${target.label}. Tap to change target.`
            : 'Compass. Tap to pick a target.'
        }
        aria-expanded={pickerOpen}
        onClick={() => setPickerOpen(o => !o)}
        sx={{
          ...GLASS_SX,
          borderRadius: 4,
          px: 1.25,
          py: 1,
          display: 'flex',
          alignItems: 'center',
          gap: 1.25,
          textTransform: 'none',
        }}
      >
        <Box
          sx={{
            position: 'relative',
            width: 46,
            height: 46,
            borderRadius: '50%',
            border: '1px solid rgba(120, 200, 225, 0.5)',
            flexShrink: 0,
          }}
        >
          {target && guidance.headingSource === 'north' && (
            <Typography
              component="span"
              variant="caption"
              sx={{
                position: 'absolute',
                top: 1,
                left: '50%',
                transform: 'translateX(-50%)',
                fontSize: '0.55rem',
                opacity: 0.85,
              }}
            >
              N
            </Typography>
          )}
          <Box
            component="span"
            data-testid="stroll-compass-arrow"
            sx={{
              position: 'absolute',
              inset: 0,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '1.15rem',
              transform: `rotate(${(target && guidance.arrowDeg !== null ? guidance.arrowDeg : 0) - 90}deg)`,
              transition: 'transform 0.25s ease',
            }}
          >
            {target ? '➤' : '🧭'}
          </Box>
        </Box>
        <Box sx={{ textAlign: 'left', minWidth: 0 }}>
          <Typography
            variant="body2"
            sx={{ fontWeight: 700, lineHeight: 1.15, whiteSpace: 'nowrap' }}
          >
            {target ? `${TARGET_EMOJI[target.kind]} ${target.label}` : '🧭 Compass'}
          </Typography>
          <Typography
            variant="caption"
            sx={{ opacity: 0.9, lineHeight: 1.15, display: 'block', whiteSpace: 'nowrap' }}
          >
            {statusLine}
          </Typography>
        </Box>
      </Button>
    </Box>
  );
};

export default StrollCompass;
