// Event notice producer (Round 22, Eddie 2026-11-18) — the one
// honest producer for event notifications. Headless: it writes a
// record into the notifications store; it renders nothing.
//
// What it announces: the realm's next event from the Forums
// Events board (the seeded demo community's happenings — battle
// nights, raid nights, swap meets). TYPE-ONLY, by Eddie's law:
// the record is "📅 Event notification" + the event's name and
// when (a name is not message content — nobody's words ride in
// it), and a tap lands on that event's thread.
//
// Trigger discipline (mirrors the venue producer's restraint):
// - It only speaks to a player who has found the Forums at least
//   once (the forums store exists on this device) — no announcing
//   a board the player has never seen.
// - Once per day per event: the record id carries the date and
//   the store dedupes by id, so re-firing can never duplicate or
//   re-toast it. Once per session via the ref, on top of that.
// - It waits for a quiet toast stack — news doesn't pile on news.
import React, { useEffect, useRef } from 'react';
import { useNotifications } from '../contexts/NotificationsContext';
import { FORUMS_KEY, loadForums, type ForumThread } from '../utils/forums';
import { localDateString } from '../utils/presence';
import { isAppIdle } from '../utils/idleSleep';

const FIRST_CHECK_MS = 3000;
const POLL_MS = 3000;
const GIVE_UP_MS = 180000;

function pickEvent(threads: ForumThread[]): ForumThread | null {
  const events = threads.filter(t => t.board === 'events');
  if (events.length === 0) return null;
  const now = Date.now();
  const upcoming = events
    .filter(t => typeof t.startsAt === 'number' && (t.startsAt as number) >= now)
    .sort((a, b) => (a.startsAt as number) - (b.startsAt as number));
  return upcoming[0] ?? events[0];
}

const EventNoticeProducer: React.FC = () => {
  const { notify, toasts } = useNotifications();
  const firedRef = useRef(false);
  const toastsRef = useRef(toasts);
  toastsRef.current = toasts;

  useEffect(() => {
    let stopped = false;
    let poll: number | null = null;
    const startedAt = Date.now();

    // Round 36.9 Part 7a (battery audit §7 #2): the interval
    // CLEARS ITSELF when its work is done — fired, or the
    // give-up window closed — the way IncomingRequestProducer
    // already does. The shipped pattern kept waking ~20×/min
    // forever, no-oping after minute 3.
    const stop = () => {
      stopped = true;
      if (poll !== null) window.clearInterval(poll);
    };

    const attempt = () => {
      if (stopped || firedRef.current) return;
      // Idle sleep (Part 7e): producers suspend while the app
      // sleeps; the next tick after a wake decides afresh.
      if (isAppIdle()) return;
      if (Date.now() - startedAt > GIVE_UP_MS) {
        stop();
        return;
      }
      let forumsSeen = false;
      try {
        forumsSeen = localStorage.getItem(FORUMS_KEY) !== null;
      } catch {
        forumsSeen = false;
      }
      if (!forumsSeen) return;
      if (toastsRef.current.length > 0) return;
      const thread = pickEvent(loadForums());
      if (!thread) return;
      firedRef.current = true;
      notify({
        id: `event-${thread.id}-${localDateString()}`,
        kind: 'event',
        title: '📅 Event notification',
        body: thread.when ? `${thread.title} · ${thread.when}` : thread.title,
        route: `/forums?board=events&thread=${thread.id}`,
        demo: true,
      });
      // The one announcement is out — the work is done.
      stop();
    };

    const first = window.setTimeout(() => {
      attempt();
      // The first attempt may already have finished the work
      // (or the window may have closed) — only arm the poll
      // while there is still work to wait for.
      if (!stopped) poll = window.setInterval(attempt, POLL_MS);
    }, FIRST_CHECK_MS);
    return () => {
      stopped = true;
      window.clearTimeout(first);
      if (poll !== null) window.clearInterval(poll);
    };
  }, [notify]);

  return null;
};

export default EventNoticeProducer;
