// GLACER sound identity (Eddie, 2026-11-16): ONE signature
// high-energy gaming sound for the whole game — a driving
// chiptune/electronic loop plus element-flavored navitar noises,
// all SYNTHESIZED with WebAudio. No audio files, no external
// assets, nothing ripped or copyrighted: every sound is generated
// from oscillators + filtered noise in this module.
//
// Browser autoplay law, honored: browsers block audio before the
// first user interaction, so nothing even tries to play on load.
// The engine unlocks on the first pointer/key interaction anywhere
// in the app; until then the game is silent and the mute toggle in
// the Navbar is visible. Default state: sound ON (music + noises
// begin after that first interaction).
//
// MUTE IS MANDATORY AND GLOBAL: one master mute in the Navbar
// silences music AND noises together, persists in localStorage
// (glacer-sound-muted), and is respected on reload. The music
// pauses when the tab is hidden (the context suspends) and
// resumes when the player comes back.

export const SOUND_MUTE_KEY = 'glacer-sound-muted';

let ctx: AudioContext | null = null;
let masterGain: GainNode | null = null;
let musicGain: GainNode | null = null;
let sfxGain: GainNode | null = null;
let noiseBuffer: AudioBuffer | null = null;
let unlocked = false;
let seqTimer = 0;
let step = 0;
let nextStepTime = 0;

let muted = (() => {
  try {
    return localStorage.getItem(SOUND_MUTE_KEY) === '1';
  } catch {
    return false;
  }
})();

const listeners = new Set<(muted: boolean) => void>();

export function isSoundMuted(): boolean {
  return muted;
}

export function subscribeSound(fn: (muted: boolean) => void): () => void {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

export function setSoundMuted(next: boolean): void {
  muted = next;
  try {
    localStorage.setItem(SOUND_MUTE_KEY, next ? '1' : '0');
  } catch {
    // Private mode / quota: the choice still holds for this session.
  }
  if (masterGain && ctx) {
    masterGain.gain.setTargetAtTime(next ? 0 : 0.9, ctx.currentTime, 0.03);
  }
  listeners.forEach(fn => fn(muted));
}

function ensureGraph(): AudioContext | null {
  if (typeof window === 'undefined') return null;
  const AC =
    window.AudioContext ??
    (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
  if (!AC) return null;
  if (!ctx) {
    ctx = new AC();
    masterGain = ctx.createGain();
    masterGain.gain.value = muted ? 0 : 0.9;
    masterGain.connect(ctx.destination);
    musicGain = ctx.createGain();
    musicGain.gain.value = 0.34; // modest — background, never blasting
    musicGain.connect(masterGain);
    sfxGain = ctx.createGain();
    sfxGain.gain.value = 0.55;
    sfxGain.connect(masterGain);
    // Shared white-noise buffer for hats / crackle / whooshes.
    noiseBuffer = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate);
    const data = noiseBuffer.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
  }
  return ctx;
}

// The first interaction unlocks audio (browser law) and starts
// the music loop. Idempotent — safe to call from every listener.
export function unlockAudio(): void {
  if (unlocked) {
    if (ctx && ctx.state === 'suspended' && document.visibilityState !== 'hidden') {
      void ctx.resume();
    }
    return;
  }
  const ac = ensureGraph();
  if (!ac) return;
  unlocked = true;
  void ac.resume();
  startSequencer();
}

if (typeof window !== 'undefined') {
  window.addEventListener('pointerdown', unlockAudio, { passive: true });
  window.addEventListener('keydown', unlockAudio);
  document.addEventListener('visibilitychange', () => {
    if (!ctx || !unlocked) return;
    if (document.visibilityState === 'hidden') {
      void ctx.suspend(); // music + noises pause with the tab
    } else if (ctx.state === 'suspended') {
      void ctx.resume();
    }
  });
}

// ---- Music: one driving chiptune loop for the whole game --------
// 132 BPM, 8th-note sequencer, Am–F–C–G: kick on quarters, hats on
// off-8ths, a snare crack per bar, octave-driving bass and a square
// arpeggio lead. Scheduled with a lookahead timer; every voice is a
// short oscillator/noise envelope — cheap on phones.

const BPM = 132;
const STEP_DUR = 60 / BPM / 2;
const CHORDS: { root: number; tones: number[] }[] = [
  { root: 45, tones: [0, 3, 7, 12] }, // Am
  { root: 41, tones: [0, 4, 7, 12] }, // F
  { root: 48, tones: [0, 4, 7, 12] }, // C
  { root: 43, tones: [0, 4, 7, 12] }, // G
];
const midi = (m: number) => 440 * Math.pow(2, (m - 69) / 12);

function tone(opts: {
  bus: GainNode;
  type: OscillatorType;
  f0: number;
  f1?: number;
  t: number;
  dur: number;
  gain: number;
}) {
  if (!ctx) return;
  const osc = ctx.createOscillator();
  const g = ctx.createGain();
  osc.type = opts.type;
  osc.frequency.setValueAtTime(Math.max(20, opts.f0), opts.t);
  if (opts.f1 !== undefined) {
    osc.frequency.exponentialRampToValueAtTime(Math.max(20, opts.f1), opts.t + opts.dur);
  }
  g.gain.setValueAtTime(opts.gain, opts.t);
  g.gain.exponentialRampToValueAtTime(0.0001, opts.t + opts.dur);
  osc.connect(g).connect(opts.bus);
  osc.start(opts.t);
  osc.stop(opts.t + opts.dur + 0.05);
}

function noise(opts: {
  bus: GainNode;
  filter: BiquadFilterType;
  f0: number;
  f1?: number;
  q?: number;
  t: number;
  dur: number;
  gain: number;
}) {
  if (!ctx || !noiseBuffer) return;
  const src = ctx.createBufferSource();
  src.buffer = noiseBuffer;
  src.loop = true;
  const filter = ctx.createBiquadFilter();
  filter.type = opts.filter;
  filter.frequency.setValueAtTime(opts.f0, opts.t);
  if (opts.f1 !== undefined) {
    filter.frequency.exponentialRampToValueAtTime(Math.max(30, opts.f1), opts.t + opts.dur);
  }
  filter.Q.value = opts.q ?? 0.9;
  const g = ctx.createGain();
  g.gain.setValueAtTime(opts.gain, opts.t);
  g.gain.exponentialRampToValueAtTime(0.0001, opts.t + opts.dur);
  src.connect(filter).connect(g).connect(opts.bus);
  src.start(opts.t, Math.random());
  src.stop(opts.t + opts.dur + 0.05);
}

function scheduleStep(s: number, t: number) {
  if (!ctx || !musicGain) return;
  const bar = Math.floor(s / 8) % 4;
  const chord = CHORDS[bar];
  const inBar = s % 8;
  // Kick: four on the floor (every other 8th).
  if (inBar % 2 === 0) {
    tone({ bus: musicGain, type: 'sine', f0: 150, f1: 42, t, dur: 0.13, gain: 0.5 });
  }
  // Hats: the off-8ths.
  if (inBar % 2 === 1) {
    noise({ bus: musicGain, filter: 'highpass', f0: 6500, t, dur: 0.04, gain: 0.1 });
  }
  // Snare crack mid-bar.
  if (inBar === 4) {
    noise({ bus: musicGain, filter: 'bandpass', f0: 1900, q: 0.7, t, dur: 0.09, gain: 0.16 });
  }
  // Bass: driving octaves every 8th.
  tone({
    bus: musicGain,
    type: 'triangle',
    f0: midi(chord.root - 12 + (inBar % 2 === 1 ? 12 : 0)),
    t,
    dur: 0.16,
    gain: 0.22,
  });
  // Lead arp: chord tones cycling, square wave, quiet.
  const arpIdx = [0, 1, 2, 3, 2, 1, 2, 3][inBar];
  tone({
    bus: musicGain,
    type: 'square',
    f0: midi(chord.root + 12 + chord.tones[arpIdx]),
    t,
    dur: 0.11,
    gain: 0.055,
  });
}

function startSequencer() {
  if (!ctx || seqTimer) return;
  step = 0;
  nextStepTime = ctx.currentTime + 0.06;
  seqTimer = window.setInterval(() => {
    if (!ctx) return;
    while (nextStepTime < ctx.currentTime + 0.25) {
      scheduleStep(step, nextStepTime);
      step = (step + 1) % 32;
      nextStepTime += STEP_DUR;
    }
  }, 90);
}

// ---- Navitar noises + effect sounds ------------------------------
// Element flavor lives in pitch + texture: ice crystalline sine
// glissandi, fire a low saw growl through lowpassed noise, electric
// crackle bursts, water bubbling down, nature chirps, shadow a
// detuned low moan, light bright rising notes, quantum pitch-steps,
// spiritual a soft fifth.

const ELEMENT_BASE: Record<string, number> = {
  ice: 880,
  fire: 200,
  electric: 660,
  nature: 440,
  shadow: 150,
  light: 990,
  water: 520,
  quantum: 740,
  spiritual: 620,
};

function sfxReady(): boolean {
  return !!ctx && unlocked && !muted && ctx.state === 'running';
}

export function playNavitarCry(element: string): void {
  if (!sfxReady() || !ctx || !sfxGain) return;
  const el = (element || '').toLowerCase();
  const base = ELEMENT_BASE[el] ?? 520;
  const t = ctx.currentTime;
  switch (el) {
    case 'ice':
      tone({ bus: sfxGain, type: 'sine', f0: base, f1: base * 1.6, t, dur: 0.22, gain: 0.22 });
      tone({
        bus: sfxGain,
        type: 'sine',
        f0: base * 2,
        f1: base * 2.4,
        t: t + 0.09,
        dur: 0.18,
        gain: 0.12,
      });
      break;
    case 'fire':
      tone({
        bus: sfxGain,
        type: 'sawtooth',
        f0: base * 0.8,
        f1: base * 1.5,
        t,
        dur: 0.34,
        gain: 0.2,
      });
      noise({ bus: sfxGain, filter: 'lowpass', f0: 500, f1: 1400, t, dur: 0.3, gain: 0.14 });
      break;
    case 'electric':
      for (let i = 0; i < 3; i++) {
        noise({
          bus: sfxGain,
          filter: 'highpass',
          f0: 2600,
          t: t + i * 0.06,
          dur: 0.04,
          gain: 0.16,
        });
      }
      tone({
        bus: sfxGain,
        type: 'square',
        f0: base * 1.4,
        f1: base * 0.7,
        t,
        dur: 0.16,
        gain: 0.1,
      });
      break;
    case 'water':
      tone({ bus: sfxGain, type: 'sine', f0: base * 1.3, f1: base * 0.6, t, dur: 0.3, gain: 0.22 });
      tone({
        bus: sfxGain,
        type: 'sine',
        f0: base * 1.7,
        f1: base * 0.9,
        t: t + 0.1,
        dur: 0.2,
        gain: 0.1,
      });
      break;
    case 'nature':
      tone({ bus: sfxGain, type: 'triangle', f0: base, f1: base * 1.25, t, dur: 0.11, gain: 0.22 });
      tone({
        bus: sfxGain,
        type: 'triangle',
        f0: base * 1.25,
        f1: base * 1.5,
        t: t + 0.12,
        dur: 0.14,
        gain: 0.2,
      });
      break;
    case 'shadow':
      tone({ bus: sfxGain, type: 'sawtooth', f0: base, f1: base * 0.6, t, dur: 0.4, gain: 0.16 });
      tone({
        bus: sfxGain,
        type: 'sawtooth',
        f0: base * 1.02,
        f1: base * 0.62,
        t,
        dur: 0.4,
        gain: 0.12,
      });
      break;
    case 'light':
      tone({ bus: sfxGain, type: 'sine', f0: base, t, dur: 0.12, gain: 0.18 });
      tone({ bus: sfxGain, type: 'sine', f0: base * 1.25, t: t + 0.1, dur: 0.12, gain: 0.18 });
      tone({ bus: sfxGain, type: 'sine', f0: base * 1.5, t: t + 0.2, dur: 0.2, gain: 0.18 });
      break;
    case 'quantum':
      [1, 1.5, 0.9, 1.8].forEach((mult, i) => {
        tone({
          bus: sfxGain!,
          type: 'square',
          f0: base * mult,
          t: t + i * 0.07,
          dur: 0.08,
          gain: 0.1,
        });
      });
      break;
    case 'spiritual':
      tone({ bus: sfxGain, type: 'sine', f0: base, t, dur: 0.35, gain: 0.16 });
      tone({ bus: sfxGain, type: 'sine', f0: base * 1.5, t: t + 0.05, dur: 0.32, gain: 0.12 });
      break;
    default:
      tone({ bus: sfxGain, type: 'triangle', f0: base, f1: base * 1.3, t, dur: 0.24, gain: 0.2 });
  }
}

// Attack / effect sounds, keyed to the same FxKind vocabulary as
// utils/attackFx.ts: battle passes its effect events through here,
// and the Navidex Stage's ambient shots reuse the same voices at
// ambient scale (power=false, quieter).
export function playFxSound(kind: string, element: string, power?: boolean): void {
  if (!sfxReady() || !ctx || !sfxGain) return;
  const el = (element || '').toLowerCase();
  const base = ELEMENT_BASE[el] ?? 520;
  const t = ctx.currentTime;
  const vol = power ? 0.34 : 0.2;
  switch (kind) {
    case 'beam':
      tone({
        bus: sfxGain,
        type: 'sawtooth',
        f0: base * 2,
        f1: base * 0.8,
        t,
        dur: power ? 0.5 : 0.34,
        gain: vol * 0.7,
      });
      noise({
        bus: sfxGain,
        filter: 'bandpass',
        f0: base * 3,
        f1: base,
        q: 2,
        t,
        dur: power ? 0.5 : 0.32,
        gain: vol * 0.5,
      });
      break;
    case 'projectile':
      noise({
        bus: sfxGain,
        filter: 'bandpass',
        f0: 500,
        f1: 2600,
        q: 1.6,
        t,
        dur: 0.28,
        gain: vol,
      });
      break;
    case 'burst':
      noise({ bus: sfxGain, filter: 'lowpass', f0: 900, f1: 160, t, dur: 0.32, gain: vol });
      tone({ bus: sfxGain, type: 'sine', f0: base, f1: base * 0.4, t, dur: 0.3, gain: vol * 0.8 });
      break;
    case 'lunge':
      tone({
        bus: sfxGain,
        type: 'square',
        f0: base * 0.7,
        f1: base * 1.1,
        t,
        dur: 0.14,
        gain: vol * 0.7,
      });
      break;
    case 'guard':
      tone({ bus: sfxGain, type: 'sine', f0: 300, f1: 620, t, dur: 0.22, gain: 0.14 });
      break;
    case 'focus':
      tone({
        bus: sfxGain,
        type: 'triangle',
        f0: base * 0.8,
        f1: base * 1.6,
        t,
        dur: 0.4,
        gain: 0.14,
      });
      break;
    default:
      // potion / aegis / surge: a bright little sparkle.
      tone({ bus: sfxGain, type: 'sine', f0: base * 1.5, t, dur: 0.1, gain: 0.12 });
      tone({ bus: sfxGain, type: 'sine', f0: base * 2, t: t + 0.08, dur: 0.14, gain: 0.12 });
  }
}
