// Navitar training — the Stage's Train button rules (Eddie,
// 2026-11-16, locked):
// - Tapping Train starts a training session for THAT navitar.
// - Each navitar can train ONCE per day.
// - At a higher level, a navitar can train TWICE per day.
// - The limit is per-navitar: training Frostbite never touches
//   Emberwing's allowance.
// The level threshold for the second daily session is a balance
// knob, not a law: TWICE_DAILY_LEVEL is the single place to change
// when Eddie sets the real number.
export const TWICE_DAILY_LEVEL = 15;

export const TRAINING_XP = 25;
export const FEED_BOND = 5;
export const TRAIN_BOND = 3;

const TRAINING_KEY = 'glacer-training-v1';
const CARE_KEY = 'glacer-stage-care-v1';

interface TrainingRecord {
  // Local calendar date the sessions belong to (device-local, so
  // "once a day" rolls over at the player's midnight).
  date: string;
  count: number;
}

type TrainingStore = Record<string, TrainingRecord>;

function today(): string {
  const d = new Date();
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${d.getFullYear()}-${mm}-${dd}`;
}

function loadTraining(): TrainingStore {
  try {
    const raw = localStorage.getItem(TRAINING_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    return parsed && typeof parsed === 'object' ? (parsed as TrainingStore) : {};
  } catch {
    return {};
  }
}

function saveTraining(store: TrainingStore): void {
  try {
    localStorage.setItem(TRAINING_KEY, JSON.stringify(store));
  } catch {
    // Private mode / quota: cooldown still applies for the session
    // via the caller's state; persistence is best-effort.
  }
}

export function dailyTrainingLimit(level: number): number {
  return level >= TWICE_DAILY_LEVEL ? 2 : 1;
}

export function trainingsUsedToday(navitarName: string): number {
  const rec = loadTraining()[navitarName];
  return rec && rec.date === today() ? rec.count : 0;
}

export function trainingsLeftToday(navitarName: string, level: number): number {
  return Math.max(0, dailyTrainingLimit(level) - trainingsUsedToday(navitarName));
}

export function recordTraining(navitarName: string): void {
  const store = loadTraining();
  const rec = store[navitarName];
  store[navitarName] =
    rec && rec.date === today()
      ? { date: rec.date, count: rec.count + 1 }
      : { date: today(), count: 1 };
  saveTraining(store);
}

// ---- Stage care state (bond / XP / look) --------------------------
// The companion layer's memory: how much this navitar has been fed,
// trained and given — plus its stage look (Modify: crystal tint +
// gear). Local-first, per navitar name, exactly like friends and
// presence already persist in this app.
export interface StageCare {
  bond: number;
  xp: number;
  tint: string; // CSS filter applied to the stage model ('none' = true colours)
  gear: string[];
  // Player-chosen presentation accent (Round 32.5, Eddie): a hex
  // colour that overrides the element tint on the fighter's
  // podium disc + stage glow. null = the element default.
  // Stage Polish round (Eddie, 2026-11-18): this field is now the
  // PRIMARY accent (the podium disc tint) of TWO — see below.
  accent: string | null;
  // SECONDARY accent (Stage Polish round, Eddie 2026-11-18
  // ~20:55 PT — "two accent colors: primary + secondary"): the
  // colour the stage's floor glow wears. accentSecondary holds a
  // MANUALLY picked secondary; while accentSecondaryAuto is true
  // the secondary is not stored at all — it is derived from the
  // primary by matchingAccentFor (auto-match), so it re-pairs
  // the instant the primary changes. Records saved before this
  // round carry only `accent`: they migrate by default (the
  // saved accent becomes the Primary via the field above, and
  // the Secondary starts in AUTO — DEFAULT_CARE below supplies
  // both new fields to old records through getCare's spread).
  accentSecondary: string | null;
  accentSecondaryAuto: boolean;
}

const DEFAULT_CARE: StageCare = {
  bond: 0,
  xp: 0,
  tint: 'none',
  gear: [],
  accent: null,
  accentSecondary: null,
  accentSecondaryAuto: true,
};

// ---- Accent pairing (Stage Polish round) ---------------------------
// THE HARMONY RULE, in one named place: the auto-matched secondary
// for a primary colour is its COMPLEMENT — the hue rotated 180°
// around the colour wheel, saturation kept, lightness pulled to
// 0.55 so the glow reads on both the light and dark stage. Pure
// and deterministic: the same primary always pairs with the same
// secondary, on every device, forever.
export function matchingAccentFor(primaryHex: string): string {
  const m = /^#?([0-9a-f]{6})$/i.exec(primaryHex.trim());
  if (!m) return primaryHex;
  const n = parseInt(m[1], 16);
  const r = ((n >> 16) & 255) / 255;
  const g = ((n >> 8) & 255) / 255;
  const b = (n & 255) / 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const d = max - min;
  let h = 0;
  if (d !== 0) {
    if (max === r) h = ((g - b) / d) % 6;
    else if (max === g) h = (b - r) / d + 2;
    else h = (r - g) / d + 4;
    h *= 60;
    if (h < 0) h += 360;
  }
  const s = d === 0 ? 0 : d / (1 - Math.abs(2 * ((max + min) / 2) - 1));
  const hue = (h + 180) % 360;
  const sat = Math.min(1, Math.max(0, isFinite(s) ? s : 0));
  const lig = 0.55;
  const c = (1 - Math.abs(2 * lig - 1)) * sat;
  const x = c * (1 - Math.abs(((hue / 60) % 2) - 1));
  const mm = lig - c / 2;
  let rr = 0;
  let gg = 0;
  let bb = 0;
  if (hue < 60) [rr, gg, bb] = [c, x, 0];
  else if (hue < 120) [rr, gg, bb] = [x, c, 0];
  else if (hue < 180) [rr, gg, bb] = [0, c, x];
  else if (hue < 240) [rr, gg, bb] = [0, x, c];
  else if (hue < 300) [rr, gg, bb] = [x, 0, c];
  else [rr, gg, bb] = [c, 0, x];
  const to = (v: number) =>
    Math.round((v + mm) * 255)
      .toString(16)
      .padStart(2, '0');
  return `#${to(rr)}${to(gg)}${to(bb)}`;
}

// The secondary a fighter actually wears right now: the manual
// pick while the player has taken the slot by hand, otherwise the
// auto-match of the primary, otherwise null (no primary chosen —
// the stage keeps its element default glow).
export function effectiveSecondaryAccent(care: StageCare): string | null {
  if (!care.accentSecondaryAuto && care.accentSecondary) return care.accentSecondary;
  return care.accent ? matchingAccentFor(care.accent) : null;
}

type CareStore = Record<string, StageCare>;

function loadCare(): CareStore {
  try {
    const raw = localStorage.getItem(CARE_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    return parsed && typeof parsed === 'object' ? (parsed as CareStore) : {};
  } catch {
    return {};
  }
}

export function getCare(navitarName: string): StageCare {
  return { ...DEFAULT_CARE, ...(loadCare()[navitarName] ?? {}) };
}

export function updateCare(navitarName: string, updates: Partial<StageCare>): StageCare {
  const store = loadCare();
  const next = { ...getCare(navitarName), ...updates };
  store[navitarName] = next;
  try {
    localStorage.setItem(CARE_KEY, JSON.stringify(store));
  } catch {
    // Best-effort persistence (see saveTraining).
  }
  // Round 30: care readers elsewhere on the page (the power
  // tracker on the fighter's Navidex card) re-read on this
  // event, so a Stage training/feed lands on the card at once.
  try {
    window.dispatchEvent(new CustomEvent('glacer-care-changed', { detail: { name: navitarName } }));
  } catch {
    // Non-browser context: readers fall back to their mount read.
  }
  return next;
}
