// VenuePerksPanel — the perk blocks on a venue's listing (the
// World Map's selected-venue panel), Round 29 (sim §§15–16).
//
// Type A (Recognized venues only): the venue-funded perk pool —
// a live counter of sponsored $5 credits, the player's earn
// state, and redemption. The counter counts CREDITS, never
// people (the no-public-counts rule, §26, covers crowds).
//
// Type B (any venue that lists one): the venue's own perk,
// noticeboard-style (§16). GLACER lists it and steps out: the
// standing line verbatim, eligibility wording only (never an
// entitlement, never a balance), and the venue's own
// Available / Paused / Ended switch — rendered here as a clearly
// labelled demo "Venue view", the same panel a venue partner
// would use, so the flip and its player-side softening can be
// seen side by side.
//
// All demo state (utils/venuePerks.ts); the DEMO chips match the
// venue surfaces' existing framing.
import React, { useEffect } from 'react';
import { Box, Button, Chip, Typography } from '@mui/material';
import type { DemoVenue } from '../data/venues';
import { useVenue } from '../contexts/VenueContext';
import { localDateString } from '../utils/presence';
import {
  TYPE_B_STANDING_LINE,
  evaluatePerkGrant,
  getPool,
  heldCreditDate,
  isRecognizedVenue,
  loadVenuePerks,
  redeemPerkCredit,
  setTypeBStatus,
  typeBPerksForVenue,
  typeBStatus,
  useVenuePerksVersion,
  type TypeBStatus,
} from '../utils/venuePerks';

const TYPE_B_SWITCH_STATES: TypeBStatus[] = ['available', 'paused', 'ended'];

export default function VenuePerksPanel({ venue }: { venue: DemoVenue }) {
  const { checkedInVenueId } = useVenue();
  const version = useVenuePerksVersion();
  const today = localDateString();
  const checkedInHere = checkedInVenueId === venue.id;
  const recognized = isRecognizedVenue(venue.id);
  const typeBPerks = typeBPerksForVenue(venue.id);

  // The deferred half of the grant (§15.2): an activity recorded
  // before check-in (a meet-card intro finished from outside)
  // completes the pair the moment the player checks in here.
  useEffect(() => {
    if (recognized) evaluatePerkGrant(venue.id);
  }, [recognized, venue.id, checkedInVenueId, version]);

  if (!recognized && typeBPerks.length === 0) return null;

  const state = loadVenuePerks();
  const pool = getPool(venue.id);
  const held = heldCreditDate(venue.id) === today;
  const redeemedToday = state.redeemedOn[venue.id] === today;
  const activityToday = state.activityOn[venue.id] === today;

  return (
    <Box data-testid="venue-perks-panel" data-venue-id={venue.id} sx={{ mt: 2 }}>
      {recognized && (
        <Box data-testid="perk-pool" sx={{ mb: typeBPerks.length > 0 ? 2.5 : 0 }}>
          <Typography variant="subtitle1" gutterBottom>
            🎁 Sponsored perk pool <Chip label="DEMO" size="small" sx={{ ml: 1 }} />
          </Typography>
          <Typography variant="body2" color="text.secondary" paragraph>
            This pool is funded by the venue&apos;s Recognized partnership: 35% of the payment is
            ring-fenced for players at this venue. It is never GLACER revenue, and whatever is not
            redeemed rolls forward as the venue&apos;s credit.
          </Typography>
          <Typography variant="body1" data-testid="pool-counter" data-venue-id={venue.id}>
            {pool.creditsLeft} sponsored $5 credits available tonight
          </Typography>
          {pool.creditsLeft <= 0 && !held && !redeemedToday && (
            <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>
              The pool is empty tonight — credits are first-come, and unredeemed pool money always
              rolls forward for this venue.
            </Typography>
          )}
          {held ? (
            <Box sx={{ mt: 1 }}>
              <Typography variant="body2" paragraph>
                🎉 You have a $5 drink/food credit here — earned by showing up and playing.
              </Typography>
              <Button
                variant="contained"
                size="small"
                data-testid="redeem-credit"
                disabled={!checkedInHere}
                onClick={() => redeemPerkCredit(venue.id)}
              >
                Redeem $5 credit here
              </Button>
              {!checkedInHere && (
                <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>
                  Check back in at this venue to redeem it.
                </Typography>
              )}
            </Box>
          ) : redeemedToday ? (
            <Typography variant="body2" sx={{ mt: 1 }}>
              ✅ Credit redeemed today — the pool paid the venue its $5, so the venue is made whole.
            </Typography>
          ) : activityToday ? (
            <Typography variant="body2" sx={{ mt: 1 }}>
              You played here today — check in at this venue to complete the pair and earn
              today&apos;s credit.
            </Typography>
          ) : checkedInHere ? (
            <Typography variant="body2" sx={{ mt: 1 }}>
              You&apos;re checked in — battle someone or meet someone here to earn today&apos;s $5
              credit.
            </Typography>
          ) : (
            <Typography variant="body2" sx={{ mt: 1 }}>
              Check in here and battle or meet someone to earn a $5 drink/food credit — one per
              player, per venue, per day.
            </Typography>
          )}
          <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
            Credits always count for food and non-alcoholic drinks. Alcohol follows the venue&apos;s
            own 21+ rules — the venue always decides who it serves.
          </Typography>
        </Box>
      )}

      {typeBPerks.map(perk => {
        const status = typeBStatus(perk);
        return (
          <Box key={perk.id} data-testid="typeb-perk" data-perk-id={perk.id} sx={{ mb: 2 }}>
            <Typography variant="subtitle1" gutterBottom>
              📌 The venue&apos;s own perk <Chip label="DEMO" size="small" sx={{ ml: 1 }} />
            </Typography>
            <Typography variant="body1">
              <strong>{perk.item}</strong> — {perk.terms}
            </Typography>
            <Typography variant="body2" sx={{ mt: 0.5 }} data-testid="typeb-standing-line">
              {TYPE_B_STANDING_LINE}
            </Typography>
            <Typography
              variant="body2"
              color="text.secondary"
              sx={{ mt: 0.5 }}
              data-testid="typeb-eligibility"
              data-status={status}
            >
              {status === 'available'
                ? checkedInHere
                  ? 'You’re checked in here — you could ask for this at the counter.'
                  : 'Check in at this venue and you could ask for this at the counter.'
                : status === 'paused'
                  ? 'The venue has this paused right now — check with the venue about what’s on.'
                  : 'The venue has ended this one — check with the venue about what’s on now.'}
            </Typography>
            <Box data-testid="typeb-venue-switch" sx={{ mt: 1 }}>
              <Typography variant="caption" color="text.secondary" display="block" gutterBottom>
                Venue view (demo) — the venue&apos;s switch. It takes effect instantly; pausing or
                ending a perk is always the venue&apos;s call.
              </Typography>
              {TYPE_B_SWITCH_STATES.map(s => (
                <Button
                  key={s}
                  size="small"
                  variant={status === s ? 'contained' : 'outlined'}
                  data-testid={`typeb-set-${s}`}
                  data-perk-id={perk.id}
                  onClick={() => setTypeBStatus(perk.id, s)}
                  sx={{ mr: 1 }}
                >
                  {s === 'available' ? 'Available' : s === 'paused' ? 'Paused' : 'Ended'}
                </Button>
              ))}
            </Box>
          </Box>
        );
      })}
    </Box>
  );
}
