import React, { useMemo, useRef, useState } from 'react';
import { Box, Button, Chip, Container, Paper, TextField, Typography } from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import { loadFriends } from '../utils/friends';
import { PlayerAvatar } from '../components/PlayerAvatar';
import {
  allDemoPeople,
  loadKickbackHome,
  loadSocial,
  removeKickbackHome,
  saveKickbackHome,
  type KickbackHome,
} from '../utils/social';
import { REMOVED_PLACEHOLDER, roleInSpace, type SpaceModeration } from '../utils/moderation';
import {
  LockedBanner,
  MessageModMenu,
  ModBadge,
  ParticipantsPanel,
  PinnedArea,
  SystemLineRow,
  mergeFlow,
} from '../components/Moderation';

// Home Kickbacks (Option C preview build, Eddie 2026-11-16; spec:
// home-kickback-venues-spec.md).
//
// A player's home can be a friends-only mini venue: name it, choose
// which friends can see it, and when friends are in the house with
// the game on, the host taps Start Kickback and the home runs like
// a little venue — Who's Here, opt-in battles under the normal
// battle law, a kickback group chat, and navitar suggestions under
// the same approval rules as everywhere.
//
// Privacy is the feature, not an extra:
// - A home is NEVER public: not on the map, not in discovery, no
//   heat glow, no ads, no venue tracking reports.
// - The home is identified by a NAME only — never a street address.
// - Who was at a kickback is NEVER recorded: arrivals and the
//   session chat live in this page's memory only, and End Kickback
//   wipes them. Only the home's name + the host's chosen visibility
//   list persist (the host's own settings, in localStorage).
// - "Same place" in the real version is NOT raw GPS (a phone is
//   accurate to ~5–50m and drifts indoors): it is check-in +
//   geofence overlap + an overlapping live presence window, with
//   the host confirming arrivals. This demo simulates arrivals.
//
// HONEST FRAMING: demo people, on this device only. Real
// cross-player kickbacks need Phase 2 presence.

interface SessionMessage {
  from: 'you' | 'them' | 'navitar';
  author?: string;
  text: string;
  ts: number;
}

// Kickback moderation (Round 35): the host moderates the room
// like any other space — appoint moderators, pin, remove, mute,
// lock — but the state is SESSION-ONLY, held here in page state
// and wiped by End Kickback with everything else. The kickback
// privacy law outranks persistence: no record of who was in the
// room — or of what the host did in it — ever survives the night.
interface KbModState {
  moderatorIds: string[];
  mutedIds: string[];
  removedIds: string[];
  removedMsgIdx: number[];
  pinnedIdx: number[];
  locked: boolean;
  systemLines: { id: string; text: string; ts: number }[];
}

const EMPTY_KB_MOD: KbModState = {
  moderatorIds: [],
  mutedIds: [],
  removedIds: [],
  removedMsgIdx: [],
  pinnedIdx: [],
  locked: false,
  systemLines: [],
};

const Kickback: React.FC = () => {
  const people = useMemo(() => allDemoPeople(), []);
  const social = useMemo(() => loadSocial(), []);
  const [home, setHome] = useState<KickbackHome | null>(() => loadKickbackHome());
  const [nameDraft, setNameDraft] = useState('');
  const [visibleDraft, setVisibleDraft] = useState<string[]>([]);

  const friendEntries = useMemo(() => {
    const ids = loadFriends();
    return people.filter(e => ids.includes(e.person.id) && !social.blocked.includes(e.person.id));
  }, [people, social.blocked]);

  // Session state — memory ONLY, never persisted. End Kickback (or
  // leaving the page) wipes it: no record of who was here survives.
  const [arrivedIds, setArrivedIds] = useState<string[]>([]);
  const [sessionLive, setSessionLive] = useState(false);
  const [chat, setChat] = useState<SessionMessage[]>([]);
  const [draft, setDraft] = useState('');
  const [endedNote, setEndedNote] = useState(false);
  const timers = useRef<number[]>([]);
  const [kbMod, setKbMod] = useState<KbModState>(EMPTY_KB_MOD);
  const kbLineCounter = useRef(0);

  // One flag-and-notify line, in this room only, wiped with the
  // session. The host is the room's owner, so lines name them so.
  const kbAct = (patch: Partial<KbModState>, line: string) => {
    kbLineCounter.current += 1;
    const ts = Date.now();
    setKbMod(prev => ({
      ...prev,
      ...patch,
      systemLines: [
        ...prev.systemLines,
        { id: `kb-sys-${ts}-${kbLineCounter.current}`, text: line, ts },
      ],
    }));
  };

  // The shared ParticipantsPanel speaks SpaceModeration with
  // `person:<id>` keys; the room's state is person ids — adapt.
  const kbAsSpace: SpaceModeration = {
    moderatorKeys: kbMod.moderatorIds.map(id => `person:${id}`),
    mutedKeys: kbMod.mutedIds.map(id => `person:${id}`),
    removedParticipants: Object.fromEntries(kbMod.removedIds.map(id => [`person:${id}`, 0])),
    removedMessages: [],
    pinnedMessages: [],
    locked: kbMod.locked,
    systemLines: [],
  };
  const kbPersonId = (key: string) => key.slice('person:'.length);
  const inRoomIds = arrivedIds.filter(id => !kbMod.removedIds.includes(id));
  const kbParticipants = [
    { key: 'you', label: 'You' },
    ...inRoomIds.map(id => ({
      key: `person:${id}`,
      label: people.find(e => e.person.id === id)?.person.name ?? id,
    })),
  ];
  const kbFlow = mergeFlow(chat, kbMod.systemLines);
  const kbPinnedItems = kbMod.pinnedIdx
    .filter(i => !kbMod.removedMsgIdx.includes(i) && !!chat[i])
    .map(i => ({
      key: `${i}`,
      authorLabel:
        chat[i].from === 'you'
          ? 'You'
          : chat[i].from === 'navitar'
            ? 'Your navitar'
            : (chat[i].author ?? 'Friend'),
      text: chat[i].text,
    }));

  const saveHome = (name: string, visibleTo: string[]) => {
    const next = { name, visibleTo };
    saveKickbackHome(next);
    setHome(next);
  };

  const simulateArrivals = () => {
    if (!home) return;
    // Demo simulation: the friends the host chose to show the home
    // to "arrive" (host-confirmed check-in in the real version).
    setArrivedIds(home.visibleTo.filter(id => friendEntries.some(e => e.person.id === id)));
    setEndedNote(false);
  };

  const startKickback = () => {
    setSessionLive(true);
    setEndedNote(false);
    setKbMod(EMPTY_KB_MOD);
    setChat([
      {
        from: 'navitar',
        text: 'Your navitar opened the kickback room for the friends in the house. Wingman rules as always: introductions only with approval, battles only by choice.',
        ts: Date.now(),
      },
    ]);
  };

  const endKickback = () => {
    // The wipe IS the privacy law: session, arrivals and chat are
    // cleared from memory and were never written anywhere.
    // Moderation state goes with them — it was part of the night.
    setSessionLive(false);
    setArrivedIds([]);
    setChat([]);
    setDraft('');
    setKbMod(EMPTY_KB_MOD);
    timers.current.forEach(t => window.clearTimeout(t));
    timers.current = [];
    setEndedNote(true);
  };

  const sendChat = () => {
    if (!draft.trim() || !sessionLive) return;
    // Round 35: a locked room refuses new posts.
    if (kbMod.locked) return;
    const text = draft.trim();
    setChat(prev => [...prev, { from: 'you', text, ts: Date.now() }]);
    setDraft('');
    // Round 35: the reply comes from a guest who can still post
    // here — muted and removed guests never answer.
    const responder = inRoomIds
      .filter(id => !kbMod.mutedIds.includes(id))
      .map(id => people.find(e => e.person.id === id)?.person)
      .find(Boolean);
    if (responder) {
      timers.current.push(
        window.setTimeout(() => {
          setChat(prev => [
            ...prev,
            {
              from: 'them',
              author: responder.name,
              text: 'This is the way — battles at the house, winner picks the playlist 🎶',
              ts: Date.now(),
            },
          ]);
        }, 1000)
      );
    }
  };

  const visibleFriends = home
    ? friendEntries.filter(e => home.visibleTo.includes(e.person.id))
    : [];

  return (
    <Container maxWidth="md" sx={{ py: 4 }} data-testid="kickback-page">
      <Typography variant="h4" gutterBottom align="center">
        Home Kickbacks
      </Typography>
      <Typography variant="body1" color="text.secondary" align="center" sx={{ mb: 3 }}>
        Your home, run like a little venue — for your friends only, and only when you say so.
      </Typography>

      <Paper sx={{ p: 2, mb: 3, bgcolor: 'rgba(232,145,45,0.12)' }}>
        <Typography variant="body2">
          🧪 <strong>Demo — on this device only</strong>, with GLACER’s demo people. Real
          cross-player kickbacks arrive with Phase 2 presence. 🔒 Your home is{' '}
          <strong>never public</strong>: never on the map, never in discovery, no heat glow, no ads,
          no tracking reports — and when a kickback ends,{' '}
          <strong>no record of who was there is kept</strong>.
        </Typography>
      </Paper>

      {!home ? (
        <Paper sx={{ p: 3, mb: 3 }}>
          <Typography variant="h5" gutterBottom>
            Name your home
          </Typography>
          <Typography variant="body2" color="text.secondary" paragraph>
            Give it a name your friends will recognise — “Eddie’s spot”, “The Ice House”, anything
            you like. <strong>A name only: never enter a street address.</strong> GLACER doesn’t
            list homes anywhere public, and the name is all a kickback ever needs.
          </Typography>
          <TextField
            label="Home name (no address!)"
            value={nameDraft}
            onChange={e => setNameDraft(e.target.value)}
            fullWidth
            size="small"
            sx={{ mb: 2 }}
            data-testid="kickback-name-input"
          />
          <Typography variant="body2" color="text.secondary" gutterBottom>
            Which friends can see it? Only the ones you pick — nobody else ever knows it exists.
          </Typography>
          {friendEntries.length === 0 ? (
            <Typography variant="body2" color="text.secondary" paragraph>
              No friends yet — head to Friends &amp; Groups and get a request accepted first.
            </Typography>
          ) : (
            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 2 }}>
              {friendEntries.map(({ person }) => (
                <Chip
                  key={person.id}
                  label={person.name}
                  clickable
                  color={visibleDraft.includes(person.id) ? 'primary' : 'default'}
                  onClick={() =>
                    setVisibleDraft(
                      visibleDraft.includes(person.id)
                        ? visibleDraft.filter(id => id !== person.id)
                        : [...visibleDraft, person.id]
                    )
                  }
                />
              ))}
            </Box>
          )}
          <Button
            variant="contained"
            disabled={!nameDraft.trim()}
            onClick={() => saveHome(nameDraft.trim(), visibleDraft)}
          >
            Save my home
          </Button>{' '}
          <Button component={RouterLink} to="/friends" sx={{ ml: 1 }}>
            Friends &amp; Groups →
          </Button>
        </Paper>
      ) : (
        <>
          <Paper sx={{ p: 3, mb: 3 }}>
            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'center', mb: 1 }}>
              <Typography variant="h5">🏠 {home.name}</Typography>
              <Chip size="small" color="success" label="Friends only — never public" />
            </Box>
            <Typography variant="body2" color="text.secondary" paragraph>
              Visible to:{' '}
              {visibleFriends.length > 0
                ? visibleFriends.map(e => e.person.name).join(', ')
                : 'nobody yet — pick friends below'}
              . Not on the map, not in discovery, contributes nothing to heat data.
            </Typography>
            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 2 }}>
              {friendEntries.map(({ person }) => (
                <Chip
                  key={person.id}
                  label={person.name}
                  clickable
                  color={home.visibleTo.includes(person.id) ? 'primary' : 'default'}
                  onClick={() =>
                    saveHome(
                      home.name,
                      home.visibleTo.includes(person.id)
                        ? home.visibleTo.filter(id => id !== person.id)
                        : [...home.visibleTo, person.id]
                    )
                  }
                />
              ))}
            </Box>
            <Typography variant="body2" color="text.secondary" paragraph>
              📍 How “same place” works in the real version: not raw GPS — a phone is only accurate
              to about 5–50m and drifts indoors. It’s check-in + geofence overlap + being present in
              the same live window, and for homes the host confirms arrivals. Exact coordinates are
              never stored as a trail. In this demo, arrivals are simulated:
            </Typography>
            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
              <Button variant="outlined" onClick={simulateArrivals} disabled={sessionLive}>
                Simulate friends arriving (demo)
              </Button>
              <Button
                color="error"
                onClick={() => {
                  endKickback();
                  removeKickbackHome();
                  setHome(null);
                  setEndedNote(false);
                }}
              >
                Remove my home
              </Button>
            </Box>
            {arrivedIds.length > 0 && !sessionLive && (
              <Typography variant="body2" sx={{ mt: 2 }}>
                At the door:{' '}
                {arrivedIds
                  .map(id => people.find(e => e.person.id === id)?.person.name ?? id)
                  .join(', ')}{' '}
                — you’ve confirmed them in. Ready when you are:
              </Typography>
            )}
            {!sessionLive ? (
              <Button
                variant="contained"
                size="large"
                sx={{ mt: 2 }}
                disabled={arrivedIds.length === 0}
                onClick={startKickback}
                data-testid="kickback-start"
              >
                ▶ Start Kickback
              </Button>
            ) : (
              <Button
                variant="contained"
                color="error"
                size="large"
                sx={{ mt: 2 }}
                onClick={endKickback}
                data-testid="kickback-end"
              >
                ■ End Kickback
              </Button>
            )}
            {endedNote && (
              <Typography variant="body2" sx={{ mt: 2 }}>
                Kickback ended — presence cleared, the room is closed, and no record of who was here
                was kept. That’s the law, not a setting.
              </Typography>
            )}
          </Paper>

          {sessionLive && (
            <Paper sx={{ p: 3, mb: 3 }} data-testid="kickback-session">
              <Typography variant="h5" gutterBottom>
                Kickback live at {home.name}
              </Typography>
              <Typography variant="subtitle1" gutterBottom>
                Who’s Here
              </Typography>
              <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 2 }}>
                {inRoomIds.map(id => {
                  const entry = people.find(e => e.person.id === id);
                  return entry ? (
                    <Chip
                      key={id}
                      label={`${entry.person.name} · ${entry.person.navitarName} Lv ${entry.person.navitarLevel}`}
                      color="primary"
                      variant="outlined"
                    />
                  ) : null;
                })}
              </Box>
              <Typography variant="body2" color="text.secondary" paragraph>
                Battles run under the normal battle law — choose your navitar, approve the opponent,
                press START BATTLE. Nothing is ever forced, even at a kickback.
              </Typography>
              <Button
                component={RouterLink}
                to="/battle"
                variant="contained"
                color="warning"
                sx={{ mb: 3 }}
              >
                ⚔️ Battle at the kickback →
              </Button>

              {/* Moderation (Round 35): the host owns the room —
                  participants, badges, pins and the lock live
                  here, in page state only, wiped at End. */}
              <Box sx={{ display: 'flex', justifyContent: 'flex-end', mb: 1 }}>
                <Button
                  size="small"
                  variant="outlined"
                  data-testid="mod-lock-toggle"
                  onClick={() =>
                    kbAct(
                      { locked: !kbMod.locked },
                      kbMod.locked
                        ? '🔓 This kickback chat was unlocked by the owner.'
                        : "🔒 This kickback chat was locked by the owner — no new posts until it's unlocked."
                    )
                  }
                >
                  {kbMod.locked ? '🔓 Unlock kickback chat' : '🔒 Lock kickback chat'}
                </Button>
              </Box>
              <ParticipantsPanel
                mod={kbAsSpace}
                ownerKey="you"
                viewerKey="you"
                participants={kbParticipants}
                onAppoint={(key, label) =>
                  kbAct(
                    { moderatorIds: [...kbMod.moderatorIds, kbPersonId(key)] },
                    `⭐ ${label} is now a moderator here — appointed by the owner.`
                  )
                }
                onUnappoint={(key, label) =>
                  kbAct(
                    { moderatorIds: kbMod.moderatorIds.filter(id => id !== kbPersonId(key)) },
                    `⭐ ${label} is no longer a moderator here — removed by the owner.`
                  )
                }
                onMute={(key, label) =>
                  kbAct(
                    { mutedIds: [...kbMod.mutedIds, kbPersonId(key)] },
                    `🔇 ${label} was muted by the owner — their new messages won't appear here while muted.`
                  )
                }
                onUnmute={(key, label) =>
                  kbAct(
                    { mutedIds: kbMod.mutedIds.filter(id => id !== kbPersonId(key)) },
                    `🔊 ${label} was unmuted by the owner.`
                  )
                }
                onRemove={(key, label) => {
                  const id = kbPersonId(key);
                  kbAct(
                    {
                      removedIds: [...kbMod.removedIds, id],
                      moderatorIds: kbMod.moderatorIds.filter(x => x !== id),
                      mutedIds: kbMod.mutedIds.filter(x => x !== id),
                    },
                    `🚪 ${label} was removed from this space by the owner.`
                  );
                }}
              />

              <Typography variant="subtitle1" gutterBottom>
                Kickback chat
              </Typography>
              <Typography variant="body2" color="text.secondary" paragraph>
                Session-only: this chat is wiped when the kickback ends and is never saved. Navitar
                suggestions work in the room under the same approval rules — find them on the
                Friends page.
              </Typography>
              <PinnedArea
                items={kbPinnedItems}
                canMod
                onUnpin={key => {
                  const i = Number(key);
                  kbAct(
                    { pinnedIdx: kbMod.pinnedIdx.filter(x => x !== i) },
                    '📌 A message was unpinned by the owner.'
                  );
                }}
              />
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, mb: 2 }}>
                {kbFlow.map(item => {
                  if (item.kind === 'sys') {
                    return <SystemLineRow key={item.line.id} line={item.line} />;
                  }
                  const m = item.msg;
                  const i = item.index;
                  const authorPerson =
                    m.from === 'them'
                      ? people.find(e => e.person.name === m.author)?.person
                      : undefined;
                  const removedMsg = kbMod.removedMsgIdx.includes(i);
                  return (
                    <Box
                      key={i}
                      sx={{
                        alignSelf: m.from === 'you' ? 'flex-end' : 'flex-start',
                        maxWidth: '85%',
                        p: 1.25,
                        borderRadius: 3,
                        bgcolor:
                          m.from === 'you'
                            ? 'rgba(18,165,199,0.25)'
                            : m.from === 'navitar'
                              ? 'rgba(232,145,45,0.18)'
                              : 'rgba(255,255,255,0.07)',
                      }}
                    >
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                        {/* Profile picture (Round 34): beside the host's
                            own kickback messages only, only when set. */}
                        {m.from === 'you' && (
                          <PlayerAvatar size={16} testId="kickback-own-avatar" />
                        )}
                        <Typography variant="caption" color="text.secondary">
                          {m.from === 'you'
                            ? 'You'
                            : m.from === 'navitar'
                              ? 'Your navitar (wingman)'
                              : (m.author ?? 'Friend')}
                        </Typography>
                        {authorPerson && (
                          <ModBadge
                            role={roleInSpace(kbAsSpace, 'you', `person:${authorPerson.id}`)}
                          />
                        )}
                        <Box sx={{ marginLeft: 'auto' }}>
                          <MessageModMenu
                            messageKey={`${i}`}
                            pinned={kbMod.pinnedIdx.includes(i)}
                            onPin={() =>
                              kbAct(
                                { pinnedIdx: [...kbMod.pinnedIdx, i] },
                                '📌 A message was pinned by the owner.'
                              )
                            }
                            onUnpin={() =>
                              kbAct(
                                { pinnedIdx: kbMod.pinnedIdx.filter(x => x !== i) },
                                '📌 A message was unpinned by the owner.'
                              )
                            }
                            onRemove={() =>
                              kbAct(
                                {
                                  removedMsgIdx: [...kbMod.removedMsgIdx, i],
                                  pinnedIdx: kbMod.pinnedIdx.filter(x => x !== i),
                                },
                                '🛡️ A message was removed by the owner.'
                              )
                            }
                          />
                        </Box>
                      </Box>
                      {removedMsg ? (
                        <Typography
                          variant="body2"
                          sx={{ fontStyle: 'italic', opacity: 0.75 }}
                          data-testid="mod-removed-placeholder"
                        >
                          {REMOVED_PLACEHOLDER}
                        </Typography>
                      ) : (
                        <Typography variant="body2">{m.text}</Typography>
                      )}
                    </Box>
                  );
                })}
              </Box>
              {kbMod.locked ? (
                <LockedBanner
                  noun="kickback chat"
                  canMod
                  onUnlock={() =>
                    kbAct({ locked: false }, '🔓 This kickback chat was unlocked by the owner.')
                  }
                />
              ) : (
                <Box sx={{ display: 'flex', gap: 1 }}>
                  <TextField
                    value={draft}
                    onChange={e => setDraft(e.target.value)}
                    placeholder="Message the kickback…"
                    size="small"
                    fullWidth
                    onKeyDown={e => {
                      if (e.key === 'Enter') sendChat();
                    }}
                  />
                  <Button variant="contained" onClick={sendChat} disabled={!draft.trim()}>
                    Send
                  </Button>
                </Box>
              )}
              <Button component={RouterLink} to="/friends" sx={{ mt: 2 }}>
                Navitar suggestions &amp; groups →
              </Button>
            </Paper>
          )}
        </>
      )}
    </Container>
  );
};

export default Kickback;
