import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { ThemeProvider, CssBaseline } from '@mui/material';
import { NavitarProvider } from './contexts/NavitarContext';
import { AuthProvider } from './contexts/AuthContext';
import { BattleProvider } from './contexts/BattleContext';
import { RealmProvider } from './contexts/RealmContext';
import { BusinessProvider } from './contexts/BusinessContext';
import { RewardProvider } from './contexts/RewardContext';
import { NavitarFightClubProvider } from './contexts/NavitarFightClub';
import { VenueProvider } from './contexts/VenueContext';
import { PresenceProvider } from './contexts/PresenceContext';
import { NotificationsProvider } from './contexts/NotificationsContext';

// Pages
import Home from './pages/Home';
import Battle from './pages/Battle';
import NavitarCollection from './pages/NavitarCollection';
import RealmMap from './pages/RealmMap';
import Profile from './pages/Profile';
import Messages from './pages/Messages';
import { PrivacyPage, TermsPage } from './pages/Legal';
import Pirates from './pages/Pirates';
import Stroll from './pages/Stroll';
import ARView from './pages/ARView';
import Networking from './pages/Networking';
import Forums from './pages/Forums';
import Features from './pages/Features';
import VenueJoin from './pages/VenueJoin';

// The admin window is owner-only and background until launch, so
// it lazy-loads (the codebase's pattern for heavy/rare surfaces):
// its code never rides the main bundle for ordinary players.
const AdminVenues = React.lazy(() => import('./pages/AdminVenues'));
import Friends from './pages/Friends';
import Kickback from './pages/Kickback';
import Challenge from './pages/Challenge';
import Notifications from './pages/Notifications';
import Wallet from './pages/Wallet';
import Instructions from './pages/Instructions';
import { ScrollToTop } from './components/ScrollToTop';
import { ViewModeProvider } from './contexts/ViewModeContext';

// Components
import Navbar from './components/Navbar';
import BackButton from './components/BackButton';
import BottomTabBar from './components/BottomTabBar';
import Footer from './components/Footer';
import ErrorBoundary from './components/ErrorBoundary';
import IcebreakerNoticeProducer from './components/IcebreakerNoticeProducer';
import IncomingMessageProducer from './components/IncomingMessageProducer';
import EventNoticeProducer from './components/EventNoticeProducer';
import IncomingRequestProducer from './components/IncomingRequestProducer';
import BattleChallengeProducer from './components/BattleChallengeProducer';
import OwnerLoadoutSeeder from './components/OwnerLoadoutSeeder';
import { startIdleSleep } from './utils/idleSleep';
import FirstArrivalWelcome from './components/FirstArrivalWelcome';
import FirstRunTour from './components/FirstRunTour';
import VenueNotification from './components/VenueNotification';
import PromotedVenueProducer from './components/PromotedVenueProducer';
import NotificationToasts from './components/NotificationToasts';
import PasswordRecovery from './components/PasswordRecovery';

// Create theme — Modern View palette (integration build,
// 2026-11-16): the deep-ice tokens from the prototype Eddie
// approved, applied to the real app. Same dark family the game
// already wears, lifted to the icy cyan/amber system.
//
// Round 11 (2026-11-17): the theme is built from the player's
// chosen mode (contexts/ThemeModeContext.tsx, localStorage
// `glacer-theme`, DEFAULT light). ONE design, two palettes — the
// layout/components never change, only the color treatment:
// light = the prototype's white look; dark = the deep-ice set
// above. The CSS tokens in styles/modern.css flip from the same
// mode via the data-theme attribute. Round 36.7: buildTheme itself
// moved into ThemeModeContext.tsx so dark-by-design surfaces (the
// Battle landing cards) can scope themselves with the same tokens.
import { ThemeModeProvider, useThemeMode, buildTheme } from './contexts/ThemeModeContext';

// Routes wrapped in an error boundary keyed by path, so a crash on one
// page shows a fallback for that page only, and navigating away resets it.
const AppRoutes: React.FC = () => {
  const location = useLocation();
  return (
    <ErrorBoundary key={location.pathname}>
      {/* Every navigation lands at the top of the destination page
          (Round 10 add-on) — see components/ScrollToTop.tsx for the
          one exemption (the venue-focus deep link). */}
      <ScrollToTop />
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/battle" element={<Battle />} />
        {/* The challenge screen (Round 10, 2026-11-17): meeting
            someone and choosing to battle them lands HERE — the
            pairing already made (your fighter vs theirs, from the
            persisted challenge handoff), a Swap in place, and one
            ⚔️ Battle button that starts that exact duel. See
            pages/Challenge.tsx + utils/challengeHandoff.ts. */}
        <Route path="/challenge" element={<Challenge />} />
        <Route path="/collection" element={<NavitarCollection />} />
        {/* The World Map's ONE canonical landing is /map (Round 10
            cleanup, 2026-11-17): the map used to be served at BOTH
            /realm (the original route) and /map (the alias added
            2026-11-12 when a direct load of /map rendered blank) —
            two URLs for one page, with nav surfaces split between
            them. /map is the name everyone types and shares, so it
            is canonical; every nav surface points here now, and
            /realm redirects so old links/bookmarks never dead-end. */}
        <Route path="/map" element={<RealmMap />} />
        <Route path="/realm" element={<Navigate to="/map" replace />} />
        <Route path="*" element={<Navigate to="/" replace />} />
        <Route path="/profile" element={<Profile />} />
        {/* The Joe quiz is GONE (Eddie, 2026-11-12: "There should be
            no quiz, scrap the quiz. I just wanted to fight."). Joe is
            fought as a boss opponent in the normal battle flow, so
            /joe redirects to the Battle Arena, where the CHALLENGE
            JOE button pre-selects him. */}
        <Route path="/joe" element={<Navigate to="/battle" replace />} />
        <Route path="/terms" element={<TermsPage />} />
        <Route path="/privacy" element={<PrivacyPage />} />
        <Route path="/messages" element={<Messages />} />
        {/* Notifications home (Round 17, 2026-11-17): the
            permanent list behind the corner pop-ups — the top-bar
            bell lands here. One level deep, like every route, so a
            fresh load boots. */}
        <Route path="/notifications" element={<Notifications />} />
        {/* GLACER Wallet (Round 20, 2026-11-17): the house model
            made visible — Points, Deposited, Earnings, Your Share,
            Ownership, one ledger (utils/wallet.ts), the settled
            Points -> Real Bucks converter. DEMO-framed: no payment
            rail is connected (Eddie's separate approval), so no
            real money moves. Design of record:
            glacer-wallet-design-v1.md (v1 + v2/v3/v4 addenda). */}
        <Route path="/wallet" element={<Wallet />} />
        {/* Instructions (Round 32, 2026-11-18): the permanent
            FAQ home — How to Fight + the rules (the same shared
            HowToFight source Training renders), plain-language
            answers, and the first-run tour's replay door. One
            level deep, like every route, so a fresh load boots. */}
        <Route path="/instructions" element={<Instructions />} />
        <Route path="/pirates" element={<Pirates />} />
        <Route path="/stroll" element={<Stroll />} />
        <Route path="/ar" element={<ARView />} />
        {/* Networking — the presence build's front door (Eddie,
            2026-11-14): status + visibility + match contexts +
            matches, gathered from Profile/Realm Map under one
            clear nav entry. */}
        <Route path="/networking" element={<Networking />} />
        {/* Forums — meetups + events boards (Eddie, 2026-11-14).
            Board/thread selection rides in search params on this
            one route: the app ships relative asset paths, so all
            routes stay one level below the basename (a nested
            /forums/<board> path would not boot — see Forums.tsx). */}
        <Route path="/forums" element={<Forums />} />
        {/* All Features hub (Modern View integration, 2026-11-16):
            every surface of the game, one tap away — the redesign
            drops nothing. */}
        <Route path="/features" element={<Features />} />
        {/* For Venues — the Pilot Host application: businesses sign
            up to advertise / host GLACER battles (SoCal Pilot
            Corridor). Its canonical landing is the one-level
            /venues (Round 10 cleanup, 2026-11-17): the form used to
            live only at the two-level /venues/join, which a FRESH
            load cannot boot (the app ships relative asset paths —
            they resolve against the two-level route and miss; the
            Forums route comment documents the same constraint).
            /venues boots fresh; /venues/join redirects here so old
            links land in-app. */}
        <Route path="/venues" element={<VenueJoin />} />
        <Route path="/venues/join" element={<Navigate to="/venues" replace />} />
        {/* Administrator — Venue operations (Round 37-V): Eddie's
            window on the venue business. The route renders nothing
            without Owner Mode (the guard lives in the page), and the
            only door to it is on the owner's Profile. Background
            until launch — no public surface links here. */}
        <Route
          path="/admin/venues"
          element={
            <React.Suspense fallback={null}>
              <AdminVenues />
            </React.Suspense>
          }
        />
        {/* Friends & Groups — the demo social layer (Option C,
            2026-11-16): friend requests, player-made groups, group
            chats and navitar connection suggestions, all demo
            people + on-device state. Real cross-player is Phase 2. */}
        <Route path="/friends" element={<Friends />} />
        {/* Home Kickbacks — a friend's-only home run like a mini
            venue (2026-11-16): name-only, never public, session
            presence is never recorded. */}
        <Route path="/kickback" element={<Kickback />} />
      </Routes>
    </ErrorBoundary>
  );
};

const ThemedApp: React.FC = () => {
  const { mode } = useThemeMode();
  const theme = React.useMemo(() => buildTheme(mode), [mode]);
  // Idle sleep (Round 36.9 Part 7e): the app-wide inactivity
  // tracker — after ~4 untouched minutes the app goes quiet
  // (render loops stand down, CSS animations pause, producers
  // suspend); any touch wakes it instantly. Started once here.
  React.useEffect(() => {
    startIdleSleep();
  }, []);
  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      {/* AuthProvider sits outside the Router: auth state is app-wide
          and sign-in never redirects or walls anything off — signed-out
          play works exactly as before. */}
      <AuthProvider>
        {/* ViewMode (art ⇄ real 3D models) is app-wide display state
            for the Modern View toggle — it wraps everything the
            Navbar and the fighter surfaces render. */}
        <ViewModeProvider>
          <NavitarProvider>
            <BattleProvider>
              {/* Provider chain lives here so its state is shared across pages:
              NavitarFightClub reads Business + Reward, Reward reads Realm,
              and the navitar created in Battle is the same one the map
              companion reads. Do not re-wrap pages in these providers — a
              second instance would shadow this state. */}
              <RealmProvider>
                <BusinessProvider>
                  <RewardProvider>
                    <NavitarFightClubProvider>
                      {/* VenueProvider nests inside the FightClub provider: the
                      meet card adds a demo person's navitar as a FightClub
                      opponent when a challenge is accepted. */}
                      <VenueProvider>
                        <Router basename={process.env.REACT_APP_BASENAME || '/GLACER'}>
                          {/* PresenceProvider lives inside the Router (its
                            icebreaker card navigates to the map) and inside
                            VenueProvider (offers key off check-in state). */}
                          <PresenceProvider>
                            {/* Notifications (Round 17): inside
                                Presence (the icebreaker tap re-opens
                                a meet card through it) and the
                                Router (taps navigate). The store
                                feeds the bell, the corner toasts and
                                the /notifications home. */}
                            <NotificationsProvider>
                              <div className="app">
                                <Navbar />
                                {/* Universal back arrow (Round 32.6,
                                    Eddie 2026-11-18): one arrow on
                                    every page, back to the last thing
                                    you were doing. Fixed glass perch
                                    under the top bar; a live fight
                                    claims the press and exits through
                                    its own doors (utils/
                                    backNavigation.ts). Inside the
                                    Router, beside the Navbar. */}
                                <BackButton />
                                {/* Password-reset landing: reset email
                                links redirect to the app root, so the
                                set-new-password form renders above
                                whichever page the link landed on. It
                                renders nothing outside recovery mode. */}
                                <PasswordRecovery />
                                <main className="main-content">
                                  <AppRoutes />
                                </main>
                                <Footer />
                                {/* Phone bottom tab bar (Modern View,
                                  2026-11-16): renders below the md
                                  breakpoint only; desktop keeps the
                                  top nav. Inside the Router for
                                  route-aware active highlighting. */}
                                <BottomTabBar />
                                {/* The two producers are headless
                                  (Round 17): they write venue
                                  notices + icebreaker offers into
                                  the notifications store. The
                                  toasts are that store's pop-up
                                  face — the Round 3 top pills are
                                  replaced by this one system. */}
                                <IcebreakerNoticeProducer />
                                <VenueNotification />
                                {/* Round 29: promoted suggestions
                                  for Recognized venues (sim §14) —
                                  headless, labelled paid, relevance-
                                  filtered, capped at 2/day by a
                                  persisted counter, mutable. */}
                                <PromotedVenueProducer />
                                {/* Round 22: the Inbox's two
                                  producers — one seeded message
                                  arrival per session, one event
                                  announcement per day, both
                                  type-only by Eddie's law. */}
                                <IncomingMessageProducer />
                                <EventNoticeProducer />
                                {/* Round 26: seeds the demo's
                                  incoming friend requests once per
                                  device and announces each with a
                                  type-only record (type + sender's
                                  handle, nothing else). */}
                                <IncomingRequestProducer />
                                {/* Round 31: seeds the Battle
                                  screen's demo Challenges once per
                                  device. Announces nothing — the
                                  Challenges section on Battle is
                                  the surface (Round 17 kept
                                  challenge invites out of
                                  notifications). */}
                                <BattleChallengeProducer />
                                {/* Round 36.9 Part 8: the owner
                                  loadout — with Owner Mode on,
                                  seed the bag + demo points ONCE
                                  (never refills). Headless. */}
                                <OwnerLoadoutSeeder />
                                {/* Round 27: the first-arrival
                                  ecosystem welcome — app-shell level
                                  (not Home-only) so a first arrival
                                  on ANY route, deep links included,
                                  hears the house model up front. It
                                  overlays the booted page, writes only
                                  its own seen-flag, and shows exactly
                                  once per device. See
                                  components/FirstArrivalWelcome.tsx. */}
                                <FirstArrivalWelcome />
                                {/* Round 32: the first-run tour —
                                  the how-to layer AFTER the welcome
                                  (it sequences itself from the
                                  welcome's dismissal event and never
                                  stacks on it). App-shell level for
                                  the same reason as the welcome:
                                  first arrival is defined by
                                  arriving. See
                                  components/FirstRunTour.tsx +
                                  utils/tour.ts. */}
                                <FirstRunTour />
                                <NotificationToasts />
                              </div>
                            </NotificationsProvider>
                          </PresenceProvider>
                        </Router>
                      </VenueProvider>
                    </NavitarFightClubProvider>
                  </RewardProvider>
                </BusinessProvider>
              </RealmProvider>
            </BattleProvider>
          </NavitarProvider>
        </ViewModeProvider>
      </AuthProvider>
    </ThemeProvider>
  );
};

const App: React.FC = () => (
  <ThemeModeProvider>
    <ThemedApp />
  </ThemeModeProvider>
);

export default App;
