import React, { useEffect, useState } from 'react';
import { Box, IconButton, Typography } from '@mui/material';
import VolumeUpIcon from '@mui/icons-material/VolumeUp';
import VolumeOffIcon from '@mui/icons-material/VolumeOff';
import { isSoundMuted, setSoundMuted, subscribeSound, unlockAudio } from '../utils/sound';

// The master sound toggle (Eddie, 2026-11-16: "mute is
// mandatory"). One control in the Navbar, next to the ART/3D
// switch, silences EVERYTHING — the background music loop and all
// navitar noises — and the choice persists in localStorage
// (glacer-sound-muted), so a muted game stays muted on reload.
// Sound is ON by default, but per browser law nothing plays until
// the first tap anywhere; this button's own tap also unlocks.
const SoundToggle: React.FC = () => {
  const [muted, setMuted] = useState<boolean>(() => isSoundMuted());

  useEffect(() => subscribeSound(setMuted), []);

  const onClick = () => {
    unlockAudio();
    setSoundMuted(!muted);
  };

  return (
    <Box sx={{ display: 'flex', alignItems: 'center', mr: 0.5 }}>
      <IconButton
        color="inherit"
        onClick={onClick}
        aria-label={muted ? 'Unmute sound' : 'Mute sound'}
        aria-pressed={muted}
        data-testid="nav-sound-toggle"
        size="small"
      >
        {muted ? <VolumeOffIcon /> : <VolumeUpIcon />}
      </IconButton>
      <Typography
        variant="caption"
        sx={{ display: { xs: 'none', sm: 'block' }, color: 'text.secondary' }}
      >
        {muted ? 'Muted' : 'Sound'}
      </Typography>
    </Box>
  );
};

export default SoundToggle;
