import React, { createContext, useContext, useEffect, useMemo, useState } from 'react';
import { createTheme, type Theme } from '@mui/material/styles';

// Theme mode (Round 11, 2026-11-17 — Eddie: "give them the
// choice"). ONE design — the Modern View — in two palettes:
//   light = the Modern View prototype's white look (the DEFAULT:
//           the white look is the front door)
//   dark  = the same design in the deep-ice palette (one tap away,
//           easier on OLED battery)
// The mode drives BOTH the MUI palette (App.tsx builds its theme
// from it) and the CSS tokens (modern.css scopes its light token
// set under :root[data-theme='light']). It persists per device in
// localStorage `glacer-theme`; public/index.html sets the
// data-theme attribute from that key before first paint, so a
// returning player never flashes the wrong theme.
export type GlacerThemeMode = 'light' | 'dark';

export const THEME_STORAGE_KEY = 'glacer-theme';

export function readStoredThemeMode(): GlacerThemeMode {
  try {
    return window.localStorage.getItem(THEME_STORAGE_KEY) === 'dark' ? 'dark' : 'light';
  } catch {
    return 'light';
  }
}

// The ONE theme builder (moved here from App.tsx in Round 36.7 so
// other surfaces can build the same tokens): App builds the app
// theme from the player's mode, and a surface that is dark BY
// DESIGN in both modes — the Battle landing's deep-ice cards —
// scopes itself with buildTheme('dark') so its text, dividers and
// controls always resolve the dark palette on the dark surface,
// whatever the app's mode. ONE design, two palettes; the tokens
// live here and nowhere else.
export function buildTheme(mode: GlacerThemeMode): Theme {
  return createTheme({
    palette: {
      mode,
      primary: {
        main: mode === 'dark' ? '#12a5c7' : '#0b7d9b',
      },
      secondary: {
        main: '#e8912d',
      },
      background: {
        default: mode === 'dark' ? '#050f16' : '#edf5f8',
        paper: mode === 'dark' ? '#0a2531' : '#ffffff',
      },
      ...(mode === 'light'
        ? {
            text: {
              primary: '#0d2b38',
              secondary: 'rgba(13, 43, 56, 0.68)',
            },
          }
        : {}),
    },
    shape: {
      borderRadius: 16,
    },
    typography: {
      fontFamily: '"Roboto", "Helvetica", "Arial", sans-serif',
    },
  });
}

interface ThemeModeValue {
  mode: GlacerThemeMode;
  setMode: (mode: GlacerThemeMode) => void;
}

const ThemeModeContext = createContext<ThemeModeValue>({ mode: 'light', setMode: () => {} });

export const ThemeModeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [mode, setModeState] = useState<GlacerThemeMode>(() => {
    const initial = readStoredThemeMode();
    // Set the attribute synchronously during first render too —
    // the index.html pre-paint script normally beats us to it, but
    // this keeps the attribute right if that script was blocked.
    if (typeof document !== 'undefined') document.documentElement.dataset.theme = initial;
    return initial;
  });

  const setMode = (next: GlacerThemeMode) => {
    setModeState(next);
    try {
      window.localStorage.setItem(THEME_STORAGE_KEY, next);
    } catch {
      /* storage unavailable — the choice still applies this session */
    }
  };

  useEffect(() => {
    document.documentElement.dataset.theme = mode;
  }, [mode]);

  const value = useMemo(() => ({ mode, setMode }), [mode]);
  return <ThemeModeContext.Provider value={value}>{children}</ThemeModeContext.Provider>;
};

export function useThemeMode(): ThemeModeValue {
  return useContext(ThemeModeContext);
}
